      "content": "{\n  \"name\": \"dsh-voice-mode\",\n  \"description\": \"Voice plugin for DeepSeek Harness: local streaming speech recognition into editable drafts, sentence-by-sentence read-aloud with captions, and voice interruption. Edge online or local VITS/Kokoro TTS; host compatibility is bounded by engines.dsh.\",\n  \"icon\": \"./icon.svg\",\n  \"version\": \"0.7.37\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/qishuilalala/dsh-voice-mode.git\"\n  },\n  \"homepage\": \"https://github.com/qishuilalala/dsh-voice-mode#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/qishuilalala/dsh-voice-mode/issues\"\n  },\n  \"engines\": {\n    \"node\": \">=18.0.0\",\n    \"dsh\": \">=0.1.1-rc.2 <0.3.0-0\"\n  },\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/msedge-tts.cjs\",\n    \"lib/tts-vits-worker.cjs\",\n    \"lib/client.js\",\n    \"lib/sense-worker.mjs\",\n    \"cordis.patch.yml\",\n    \"icon.svg\",\n    \"locale/*.json\",\n    \"assets/architecture.svg\",\n    \"scripts/prefetch.mjs\",\n    \"scripts/list-voices.mjs\",\n    \"scripts/bench-asr.mjs\",\n    \"scripts/verify.mjs\",\n    \"scripts/check-anchors.mjs\",\n    \"README.md\",\n    \"README.en.md\",\n    \"LICENSE\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"SECURITY.md\"\n  ],\n  \"scripts\": {\n    \"build\": \"node build.mjs\",\n    \"check:lib-drift\": \"node scripts/check-lib-drift.mjs\",\n    \"prepack\": \"node build.mjs\",\n    \"test\": \"node scripts/run-tests.mjs\",\n    \"verify:client\": \"node test/verify-client.mjs\",\n    \"prefetch\": \"node scripts/prefetch.mjs\",\n    \"list-voices\": \"node scripts/list-voices.mjs\",\n    \"bench-asr\": \"node scripts/bench-asr.mjs\",\n    \"bench:echo-gate\": \"node scripts/bench-echo-gate.mjs\",\n    \"analyze:fixture\": \"node scripts/analyze-fixture.mjs\",\n    \"verify\": \"node scripts/verify.mjs\",\n    \"typecheck\": \"node node_modules/typescript/bin/tsc -p tsconfig.json --noEmit && node node_modules/typescript/bin/tsc -p tsconfig.client.json --noEmit\",\n    \"check:anchors\": \"node scripts/check-anchors.mjs\",\n    \"check:doc-anchors\": \"node scripts/check-doc-anchors.mjs\",\n    \"typecheck:dual\": \"bash scripts/typecheck-dual.sh\",\n    \"smoke:runtime\": \"bash scripts/smoke-runtime.sh\",\n    \"verify:dual\": \"bash scripts/verify-dual.sh\",\n    \"e2e:full\": \"bash scripts/full-e2e.sh\",\n    \"check:root-manifest\": \"node scripts/check-root-manifest.mjs\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-cordis-client-runner\",\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\"\n      ]\n    }\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.5\",\n    \"sherpa-onnx\": \"^1.13.6\",\n    \"sherpa-onnx-node\": \"1.13.6\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"react\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-llm\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-settings\": \"0.1.5-rc.1\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.1.5-rc.3\",\n    \"@types/node\": \"^26.6.5\",\n    \"@types/react\": \"^19.3.0\",\n    \"esbuild\": \"^0.28.2\",\n    \"msedge-tts\": \"^2.1.1\",\n    \"playwright-core\": \"1.65.0\",\n    \"typescript\": \"^5.9.2\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"voice\",\n    \"voice-mode\",\n    \"speech\",\n    \"asr\",\n    \"tts\",\n    \"speech-to-text\",\n    \"text-to-speech\",\n    \"speech-recognition\",\n    \"full-duplex\",\n    \"duplex\",\n    \"barge-in\",\n    \"captions\",\n    \"wake-word\",\n    \"local-asr\",\n    \"on-device\",\n    \"zipformer2\",\n    \"sensevoice\",\n    \"kokoro\",\n    \"msedge-tts\",\n    \"chinese\",\n    \"语音\",\n    \"字幕\",\n    \"打断\",\n    \"中文\",\n    \"本地识别\"\n  ],\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"license\": \"MIT\"\n}\n"
